export type Tokens = typeof tokens;
export type TokenPath = keyof Tokens;
type PathOf<Type extends string> = { [P in TokenPath]: Tokens[P]["type"] extends Type ? P : never }[TokenPath];
export type ColorPath = PathOf<"color">;
export type DimensionPath = PathOf<"dimension">;

/** The CSS reference to a token's custom property, such as var(--sb-palette-deep). */
export const cssVar = <P extends TokenPath>(path: P) => `var(${tokens[path].name})` as const;

/** A colour token's hex value, with any reference resolved. */
export const hex = (path: ColorPath): string => tokens[path].value.hex;

/** A dimension token's value in its own unit, with any reference resolved. */
export const amount = (path: DimensionPath): number => tokens[path].value.value;
